import sympy as S
from fractions import Fraction as F
from .common import item,study,section,formula
x=S.symbols('x')
def q(n,stem,a,wrong,work,hints,decision,check,method,level=3):
 return item(f'polynomial-structure-q{n:02d}',stem,a,wrong,work,hints,decision=decision,skills=['root-coefficient structure','polynomial constraints'],check=check,check_method=method,level=level)
def rootsum(poly,fn):return S.simplify(sum(fn(r) for r in S.solve(poly,x)))
p=[
q(1,r'The roots of $2t^3-7t^2+3t+5$ are $r,s,u$, counted with multiplicity. Find $(r+1)(s+1)(u+1)$.',F(7,2),[(7,'Forget the leading coefficient.'),(F(-7,2),'Lose the sign from three negative factors.'),(F(5,2),'Use the original constant term without shifting.'),(F(9,2),'Evaluate the polynomial at +1 instead of -1.')],
 [r'Factor the polynomial as $P(t)=2(t-r)(t-s)(t-u)$.',r'At $t=-1$, each factor is the negative of the factor requested, so $P(-1)=-2(r+1)(s+1)(u+1)$.',r'Since $P(-1)=-7$, the product is $7/2$.'],['Match the desired product to a polynomial evaluation.','Account for both the leading coefficient and the three signs.'],'Recover a shifted product without finding individual roots.',lambda:F(-((-1)**3*2-7*(-1)**2+3*(-1)+5),2),'Direct polynomial evaluation with the root-factorization identity.',2),
q(2,r'The roots of $t^3-4t^2+2t+3$ are $a,b,c$. What is $1/a+1/b+1/c$?',F(-2,3),[(F(2,3),'Lose the sign of the cubic root product.'),(F(-4,3),'Use the sum of roots instead of the pair sum.'),(F(-3,2),'Invert the reciprocal-sum formula.'),(2,'Omit the common product denominator.')],
 [r'The nonzero constant term ensures that none of the roots is zero.',r'Vieta gives $ab+bc+ca=2$ and $abc=-3$.',r'Combining the reciprocals gives $(ab+bc+ca)/(abc)=-2/3$.'],['Use one denominator for the three reciprocals.','Read the pair sum and the signed root product from the cubic.'],'Choose the elementary symmetric quantities that match a reciprocal target.',lambda:rootsum(x**3-4*x*x+2*x+3,lambda r:1/r),'Exact symbolic roots substituted into the reciprocal sum.',2),
q(3,r'A polynomial $P$ of degree at most $3$ satisfies $P(0)=1$, $P(1)=2$, $P(2)=9$, and $P(3)=28$. Find $P(4)$.',65,[(64,'Forget the constant shift.'),(55,'Continue only the last difference as if it were constant.'),(81,'Guess a square pattern from too few values.'),(66,'Shift the input rather than the output.')],
 [r'The simple polynomial $Q(t)=t^3+1$ matches all four supplied values.',r'The polynomial $P-Q$ has degree at most three and four distinct roots. It must be the zero polynomial.',r'Hence $P(4)=4^3+1=65$. Matching a pattern alone would not suffice without the degree bound.'],['Look for a simple polynomial that fits all four values.','Use the degree bound to justify uniqueness, not just to guess a pattern.'],'Turn enough exact values into a polynomial identity.',lambda:S.interpolate([(0,1),(1,2),(2,9),(3,28)],x).subs(x,4),'Independent interpolation of the four data points.',2),
q(4,r'When a polynomial $P(t)$ is divided by $(t-1)(t-2)$, its remainder is $R(t)$. If $P(1)=4$ and $P(2)=7$, what is $R(5)$?',16,[(7,'Assume the remainder is constant.'),(15,'Omit the remainder’s constant coefficient.'),(25,'Substitute into an unsupported quadratic remainder.'),(31,'Interpolate P itself despite its unrestricted degree.')],
 [r'The remainder has degree less than two, so write $R(t)=At+B$.',r'At roots of the divisor, $P=R$. Thus $A+B=4$ and $2A+B=7$, giving $A=3,B=1$.',r'Therefore $R(5)=16$. The data do not determine $P(5)$, only the remainder at 5.'],['The divisor bounds the degree of the remainder.','Evaluate the division identity at the two roots of the divisor.'],'Interpolate the small remainder rather than the original polynomial.',lambda:S.interpolate([(1,4),(2,7)],x).subs(x,5),'Interpolate the unique affine remainder.',2),
q(5,r'The remainder when $t^{10}$ is divided by $t^2-t-1$ is $At+B$. Find $A+B$.',89,[(55,'Report only the coefficient of t.'),(34,'Report only the constant coefficient.'),(144,'Use one extra power in the recurrence.'),(1,'Substitute t=1 into the original power before reducing modulo the polynomial.')],
 [r'Modulo the divisor, $t^2=t+1$. If $t^n$ has remainder $A_nt+B_n$, multiplying by $t$ gives $A_{n+1}=A_n+B_n$ and $B_{n+1}=A_n$.',r'Starting with $(A_1,B_1)=(1,0)$ produces $(A_{10},B_{10})=(55,34)$.',r'The requested sum is $89$. Substituting t=1 before taking the remainder is invalid because 1 is not a root of the divisor.'],['Replace every quadratic power using the divisor relation.','Track just the two coefficients through multiplication by t.'],'Represent a large power by a two-state recurrence.',lambda:sum(S.Poly(S.rem(x**10,x*x-x-1,x),x).all_coeffs()),'Direct exact polynomial division, independent of the coefficient recurrence.'),
q(6,r'A monic polynomial $P$ of degree $4$ satisfies $P(1)=P(2)=P(3)=P(4)=7$. What is $P(5)$?',31,[(7,'Assume four equal values force a quartic to be constant.'),(24,'Compute P(5)-7 but do not restore the shift.'),(127,'Use the product 1·2·3·4·5 instead of four shifted factors.'),(32,'Add an incorrect constant after factoring.')],
 [r'The polynomial $P(t)-7$ is monic of degree four and has the four distinct roots $1,2,3,4$.',r'It is therefore exactly $(t-1)(t-2)(t-3)(t-4)$. There is no additional polynomial factor or nonunit leading coefficient.',r'At $t=5$, this gives $P(5)=4\cdot3\cdot2\cdot1+7=31$.'],['Subtract the common value before using the roots.','Use both the degree and the monic condition to identify the entire polynomial.'],'Convert equal values into a known root factorization.',lambda:(S.prod(x-k for k in range(1,5))+7).subs(x,5),'Construct the monic polynomial from four prescribed roots and verify all four values.'),
q(7,r'Let $r_1,r_2,r_3,r_4$ be the four real roots of $t^4-5t^2+5=0$. What is $r_1^6+r_2^6+r_3^6+r_4^6$?',100,[(50,'Count each squared root only once.'),(250,'Cube the sum of squared-root values without cross terms.'),(125,'Ignore both the cross terms and the two-to-one substitution.'),(40,'Compute a lower power sum.')],
 [r'Let $u=t^2$. The two roots $a,b$ of $u^2-5u+5=0$ are positive because their sum is 5, product is 5, and discriminant is positive.',r'Each positive u gives two opposite real t roots. Therefore the requested sum is $2(a^3+b^3)$.',r'Using $a+b=5,ab=5$ gives $2(125-75)=100$. The factor of two records the multiplicity introduced by the substitution.'],['Treat the quartic as a quadratic in t².','Track how many original roots correspond to each new root.'],'Combine a substitution with root multiplicities and symmetric cubes.',lambda:rootsum(x**4-5*x*x+5,lambda r:r**6),'Solve the quartic exactly and sum the sixth powers.'),
q(8,r'The roots of $t^3-3t+1$ are $a,b,c$. Find $\frac{(a-1)(b-1)(c-1)}{(a+1)(b+1)(c+1)}$.',F(-1,3),[(F(1,3),'Lose the sign in one of the evaluations.'),(-3,'Invert the requested ratio.'),(1,'Assume both shifted products have the same value.'),(3,'Invert the ratio and also lose the sign.')],
 [r'For this monic cubic, $(a-1)(b-1)(c-1)=-P(1)$ and $(a+1)(b+1)(c+1)=-P(-1)$.',r'The signs cancel in the ratio. The denominator is nonzero since $P(-1)=3$.',r'Compute $P(1)=-1$ and obtain $P(1)/P(-1)=-1/3$.'],['Both products are evaluations of the same polynomial.','Write the signs explicitly before taking the quotient.'],'Evaluate a ratio of shifted root products.',lambda:F((1**3-3*1+1),((-1)**3-3*(-1)+1)),'Direct evaluation of both polynomial factors, with a nonzero denominator check.',2),
q(9,r'A polynomial $P$ with integer coefficients satisfies $P(2)=5$ and $P(5)=17$. Which of the following cannot equal $P(8)$?',38,[(11,'This is attained by 4t-3-(t-2)(t-5).'),(29,'This is attained by the linear polynomial 4t-3.'),(47,'This is attained by adding (t-2)(t-5) to 4t-3.'),(65,'This is attained by adding twice (t-2)(t-5) to 4t-3.')],
 [r'The polynomial $Q(t)=P(t)-(4t-3)$ has integer coefficients and vanishes at both 2 and 5. Dividing by the monic factors shows $Q(t)=(t-2)(t-5)H(t)$ with integer-coefficient H.',r'At 8, $P(8)=29+18H(8)$, so its value must be congruent to 29 modulo 18. The value 38 does not meet that requirement.',r'The other choices occur by choosing H to be the constant -1, 0, 1, or 2, respectively. This proves their attainability as well as excluding 38.'],['Subtract a simple polynomial that already matches the two values.','The difference has two integer roots, so evaluate its two factors at 8.'],'Use polynomial divisibility to get a sharp integer restriction.',lambda:next(v for v in [11,29,38,47,65] if (v-29)%18),'Check the residue obstruction and construct an explicit polynomial for every other option.'),
q(10,r'Real numbers $a,b,c$ satisfy $a+b+c=3$, $a^2+b^2+c^2=11$, and $a^3+b^3+c^3=27$. Find $a^4+b^4+c^4$.',83,[(81,'Use only the largest root or cube of the cubic sum’s base.'),(121,'Square the sum of squares without mixed terms.'),(101,'Use the wrong sign for the triple product.'),(99,'Multiply the first and third power sums only.')],
 [r'The pair sum is $e_2=(3^2-11)/2=-1$. The cubic identity $p_3=e_1^3-3e_1e_2+3e_3$ gives $27=27+9+3e_3$, so $e_3=-3$.',r'Each number satisfies $t^3-3t^2-t+3=0$. Multiplying by t and summing gives $p_4=3p_3+p_2-3p_1$.',r'Thus $p_4=81+11-9=83$. The actual unordered triple is $3,1,-1$, giving a separate check.'],['Use the first two power sums to recover the pair sum.','Recover the cubic whose roots are a,b,c, then use its equation to reduce fourth powers.'],'Recover a polynomial from power sums and use it to advance the sequence.',lambda:rootsum(x**3-3*x*x-x+3,lambda r:r**4),'Factor the reconstructed cubic and directly evaluate the fourth powers.'),
q(11,r'A monic cubic $P$ has integer roots, satisfies $P(0)=-12$, and has $P(1)=P(2)=0$. Find $P(3)$.',-6,[(6,'Lose the negative factor from the third root.'),(-12,'Use the constant term as the value at 3.'),(2,'Ignore the third factor.'),(12,'Use the root product instead of the requested evaluation.')],
 [r'Two roots are 1 and 2. Write $P(t)=(t-1)(t-2)(t-r)$ using the monic cubic condition.',r'At zero, $P(0)=-2r=-12$, so $r=6$.',r'Therefore $P(3)=(2)(1)(-3)=-6$.'],['Use the known roots before introducing unknown coefficients.','The constant term determines the remaining root.'],'Use a root factorization with the constant coefficient.',lambda:S.expand((x-1)*(x-2)*(x-6)).subs(x,3),'Expand the independently determined polynomial and verify all three data values.',2),
q(12,r'The remainder when $(t+1)^6-(t-1)^6$ is divided by $t^2+1$ is $At+B$. Find $A$.',-16,[(16,'Use t²=1 instead of t²=-1.'),(0,'Assume subtraction removes the odd powers.'),(12,'Retain only the linear term before reduction.'),(64,'Add the remaining coefficients without alternating signs.')],
 [r'The even powers cancel, leaving $12t^5+40t^3+12t$.',r'Modulo $t^2+1$, one has $t^3=-t$ and $t^5=t$.',r'The remainder is $(12-40+12)t=-16t$, so $A=-16$. This uses real polynomial arithmetic and does not require complex numbers.'],['Use parity to avoid expanding terms that cancel.','Reduce the surviving powers using t²=-1.'],'Combine parity cancellation with a quadratic remainder relation.',lambda:S.Poly(S.rem((x+1)**6-(x-1)**6,x*x+1,x),x).coeff_monomial(x),'Direct symbolic polynomial division.'),
q(13,r'A polynomial $P$ of degree at most 4 satisfies $P(t)+P(-t)=2t^4+6t^2+8$, $P(1)=10$, and $P(2)-P(-2)=20$. Find $P(3)$.',142,[(112,'Omit the odd part.'),(140,'Omit part of the linear contribution.'),(164,'Double the odd part.'),(284,'Forget to halve the even-part identity.')],
 [r'The even part is $t^4+3t^2+4$, so write $P(t)=t^4+at^3+3t^2+bt+4$.',r'The two remaining conditions give $a+b=2$ and $16a+4b=20$. Solving yields $a=b=1$.',r'Thus $P(3)=81+27+27+3+4=142$. The even/odd decomposition reduces the unknown coefficients before the linear system is solved.'],['Separate the even powers from the odd powers.','Subtraction at opposite inputs isolates the unknown odd part.'],'Exploit symmetry to reduce the dimension of a coefficient problem.',lambda:(x**4+x**3+3*x*x+x+4).subs(x,3),'Solve the full coefficient conditions symbolically and evaluate the resulting polynomial.'),
q(14,r'The three roots $a,b,c$ of $3t^3-18t^2+29t-10$ are distinct. What is $\frac1{a(a-1)}+\frac1{b(b-1)}+\frac1{c(c-1)}$?',F(-17,5),[(F(17,5),'Reverse the partial-fraction subtraction.'),(F(12,5),'Add the two reciprocal sums.'),(F(-1,2),'Compute only the shifted reciprocal sum.'),(F(29,10),'Compute only the unshifted reciprocal sum.')],
 [r'Use $1/[t(t-1)]=1/(t-1)-1/t$. The unshifted reciprocal sum is $29/10$ by Vieta.',r'Writing $u=t-1$ gives the shifted polynomial $3u^3-9u^2+2u+4$. Its reciprocal-root sum is $-2/4=-1/2$. Neither denominator can vanish because the original polynomial is nonzero at 0 and 1.',r'The requested difference is $-1/2-29/10=-17/5$. This combines a rational decomposition with a change of polynomial variable.'],['Split each reciprocal product into two simpler fractions.','Use a shifted polynomial to describe the roots a-1,b-1,c-1.'],'Coordinate a partial-fraction identity with shifted Vieta data.',lambda:rootsum(3*x**3-18*x*x+29*x-10,lambda r:1/(r*(r-1))),'Factor the cubic and substitute its exact three roots into the original expression.')]

examples=[
item('polynomial-structure-example-1',r'The roots of $P(t)=t^3-5t^2+7t-2$ are $a,b,c$. Find $(3-a)(3-b)(3-c)$.',1,[(2,'Use the constant coefficient.'),(-1,'Insert an unnecessary odd-degree sign.'),(3,'Use the input instead of the evaluation.'),(7,'Use only the linear coefficient.')],
 [r'The requested product uses every root exactly once and with the same shift. That is the shape of the root factorization, not a cue to solve a cubic.',r'Because P is monic, $P(t)=(t-a)(t-b)(t-c)$. The target is therefore exactly $P(3)$.',r'Evaluate $27-45+21-2=1$.',r'If the factors had instead been $(a-3)(b-3)(c-3)$, the result would have the opposite sign. If the polynomial were nonmonic, its leading coefficient would have to be divided out.',r'For a check, P factors as $(t-2)(t^2-3t+1)$; the quadratic pair contributes $(3-a)(3-b)=1$ and the remaining factor is also 1.'],['Look for the root factorization of the polynomial.','The order of subtraction determines whether a sign appears.'],decision='Identify a root product as a polynomial evaluation.',skills=['shifted root product'],check=S.simplify(S.prod(3-r for r in S.solve(x**3-5*x*x+7*x-2,x))),check_method='Factor P=(t-2)(t²-3t+1) and evaluate the two factors at 3.',level=2),
item('polynomial-structure-example-2',r'What is the remainder when $t^8$ is divided by $t^2-t-2$? Give the sum of its two coefficients.',171,[(85,'Report only the linear coefficient.'),(86,'Report only the constant coefficient.'),(257,'Add the two values without interpolating.'),(255,'Subtract the values but omit division by the input difference.')],
 [r'The remainder must be $At+B$. The divisor factors as $(t-2)(t+1)$, so these two inputs annihilate the quotient term in the division identity.',r'At 2 the remainder is 256, and at -1 it is 1. Thus $2A+B=256$ and $-A+B=1$.',r'Subtraction gives $3A=255$, so $A=85$ and $B=86$. Their sum is 171.',r'These two values determine an affine remainder uniquely. They do not determine the full degree-eight polynomial; the degree bound on the remainder is the essential reason the method works.',r'An independent check reduces powers repeatedly using $t^2=t+2$ and gives the same remainder $85t+86$.'],['Find the roots of the divisor, not of the dividend.','At either divisor root, the original power equals the small remainder.'],decision='Replace high-degree division with a two-equation interpolation problem.',skills=['remainder degree','factor theorem','interpolation'],check=S.rem(x**8,x*x-x-2,x).subs(x,1),check_method='Exact polynomial division followed by evaluation of the remainder at 1.',level=3)
]
study('polynomial-structure','Polynomial structure, shifted roots & remainders','Algebra','polynomials vieta identities',14,'183–208',
 [r'A polynomial problem becomes manageable when you decide which representation to use: coefficients, roots, values, or a remainder. Moving between these forms often avoids solving for any root. The main task is to recognize the representation in which the requested quantity is already visible.',r'Try the first example before reading its solution: a cubic is given, but the target is a product involving all three roots with the same shift. Treating the problem as three separate root computations would throw away the structure that makes it short.'],
 [section('Read products and sums from the right representation',r'If a degree-n polynomial has leading coefficient A and roots $r_1,\ldots,r_n$, counted with multiplicity, then $P(t)=A\prod(t-r_i)$. A product of identically shifted roots is an evaluation of P. Every factor must be included with the correct sign, and A must be removed if the polynomial is not monic. These details are part of the reasoning, not cosmetic corrections at the end.',r'Vieta follows by expanding the same product. For a monic cubic $t^3-e_1t^2+e_2t-e_3$, the coefficients encode the root sum, pair sum, and triple product. To obtain a reciprocal sum, first combine the fractions: $1/a+1/b+1/c=(ab+bc+ca)/(abc)$. This tells you which coefficients matter and also identifies the condition $abc\ne0$.',r'A shifted target can require shifted coefficients. If the new roots are $r_i-h$, substitute $t=u+h$ into P. Expanding this one polynomial is often much easier than finding each root and subtracting h separately. Partial fractions may first split a complicated target into an unshifted and a shifted reciprocal sum.'),
 section('Use degree bounds to turn observations into proofs',r'A nonzero polynomial of degree d has at most d distinct roots. Consequently, two polynomials of degree at most d that agree at d+1 distinct inputs agree everywhere. A numerical pattern can suggest a candidate, but this theorem is the reason enough observations determine it.',r'Equal values become roots after subtraction. If a monic quartic takes the value c at four different inputs, then subtracting c produces a monic quartic with those four roots. The leading coefficient and degree together determine the entire factorization. With a higher degree or an unspecified leading coefficient, the same conclusion would not follow.',r'Integer coefficients supply an additional invariant: if a polynomial vanishes at an integer a, division by the monic factor t-a preserves integer coefficients. Subtract a simple matching polynomial, factor out several known integer roots, and evaluate elsewhere to obtain a divisibility restriction. A necessary congruence becomes an exact description only after you also construct polynomials attaining the allowed values.'),
 section('Reduce the polynomial before reducing the arithmetic',r'Division by a degree-d polynomial leaves a remainder of degree below d. For a quadratic divisor with two distinct roots, its remainder is affine and can be found from two values. The degree bound is essential: plugging in two inputs would never determine an arbitrary polynomial.',r'If the divisor does not have convenient roots, use its relation directly. Modulo $t^2-t-1$, replace t² by t+1. Multiplying an affine remainder by t updates only two coefficients; the high power has become a small recurrence. This is polynomial modular arithmetic, not the substitution of a particular numerical value for t.',r'Parity is another useful reduction. Adding P(t) and P(-t) removes odd powers; subtraction removes even powers. Apply this before a long expansion or coefficient system. When a substitution such as u=t² is used instead, track the number and sign of the original roots associated with each u. A valid algebraic shortcut still needs a root-count and domain check.')],
 ['Choose between coefficient, root, value, and remainder representations.','Compute shifted symmetric expressions and enforce nonzero denominators.','Use degree and integer-coefficient constraints to prove uniqueness and divisibility.'],
 [r'Expand $A\prod(t-r_i)$; the coefficient of each power is the corresponding signed elementary symmetric sum.',r'Write $P=DQ+R$ with $\deg R<\deg D$. At a root u of D, the equation reduces to $P(u)=R(u)$.',r'Two affine remainders agreeing at two distinct inputs have a difference with two roots and degree at most one, so the remainders are identical.'],
 'A remainder evaluated at a number is not generally the original polynomial evaluated there. That equality is guaranteed at roots of the divisor; elsewhere the quotient term can be nonzero.',examples,p,
 dict(prompt=r'A polynomial P leaves remainder $At+B$ on division by $(t-2)(t-4)$. Given $P(2)=3$ and $P(4)=11$, find A and B, then explain why P(3) is not determined.',answer=r'$A=4$, $B=-5$; $P(3)$ is undetermined.',steps=[r'$2A+B=3$ and $4A+B=11$ imply $A=4,B=-5$.',r'The polynomials $4t-5$ and $4t-5+(t-2)(t-4)$ match both given values.',r'At 3 their values are 7 and 6, respectively, so the remainder data do not fix P(3).']),
 techniques=['shifted root products','higher Vieta','remainder interpolation','integer polynomial constraints'],released_from='polynomials')
formula('polynomial-structure',r'P(t)=A\prod_{i=1}^n(t-r_i)','Root factorization','evaluating a product involving every polynomial root with the same shift','$A$ is the leading coefficient; roots are counted with multiplicity and signs match $t-r_i$.')
formula('polynomial-structure',r'\frac1a+\frac1b+\frac1c=\frac{ab+bc+ca}{abc}','Reciprocal-root sum','recovering a reciprocal sum from a cubic’s elementary symmetric sums','All three roots are nonzero.')
formula('polynomial-structure',r'P(t)=D(t)Q(t)+R(t),\quad\deg R<\deg D','Polynomial division','replacing a large polynomial by a smaller remainder','$D$ is a nonzero polynomial; at a root $u$ of $D$, $P(u)=R(u)$.')
formula('polynomial-structure',r'P_{\mathrm{even}}(t)=\frac{P(t)+P(-t)}2','Even-part projection','isolating the even powers of a polynomial','The coefficient field has characteristic different from two; the odd part uses subtraction instead.')
